def solve():
    n = int(input())
    data = []

    for _ in range(n):
        client, orders = input().split()
        data.append([client, int(orders)])

    passes = 0

    while True:
        swapped = False

        for i in range(n - 1):
            if data[i][1] > data[i + 1][1]:
                data[i], data[i + 1] = data[i + 1], data[i]
                swapped = True

        passes += 1

        if not swapped:
            break

    for item in data:
        print(f"{item[0]} {item[1]}")

    print(f"Проходов: {passes}")


if __name__ == "__main__":
    solve()

def read_stock():
    n = int(input())
    stock = []
    for _ in range(n):
        code, left, minimum = input().split()
        stock.append((code, int(left), int(minimum)))
    return stock

def to_order(stock):
    result = []
    for code, left, minimum in stock:
        if left < minimum:
            result.append((code, minimum - left))
    return result

def main():
    stock = read_stock()
    orders = to_order(stock)
    if not orders:
        print("Дозаказ не нужен")
        return
    total = 0
    for code, amount in orders:
        print(f"{code}: дозаказать {amount}")
        total += amount
    print(f"Всего единиц к заказу: {total}")

if __name__ == '__main__':
    main()

def read_orders():
    n = int(input())
    orders = []
    for _ in range(n):
        number, total = input().split()
        orders.append((number, int(total)))
    return orders

def discount_percent(total):
    if total >= 5000000:
        return 10
    elif total >= 2000000:
        return 5
    else:
        return 0

def main():
    orders = read_orders()
    paid = 0
    for number, total in orders:
        percent = discount_percent(total)
        discount = total * percent // 100
        to_pay = total - discount
        paid += to_pay
        print(f"{number}: {total} - {percent}% = {to_pay}")
    print(f"Всего к оплате: {paid}")

if __name__ == '__main__':
    main()

